import numpy as np, heapq
from PIL import Image,ImageDraw
from scipy.ndimage import label
S=np.array(Image.open('/app/output/target_skel.png'))>0

def snap(pt):
 u,v=pt; y0=max(0,int(v)-30);y1=min(S.shape[0],int(v)+31);x0=max(0,int(u)-30);x1=min(S.shape[1],int(u)+31)
 yy,xx=np.where(S[y0:y1,x0:x1]);
 if not len(xx): raise ValueError(pt)
 j=np.argmin((xx+x0-u)**2+(yy+y0-v)**2);return (int(xx[j]+x0),int(yy[j]+y0))
def route(a,b):
 s=snap(a);t=snap(b);h=[(0.,s)];dist={s:0};prev={};
 while h:
  f,p=heapq.heappop(h);g=dist[p]
  if p==t:break
  x,y=p
  for dy in [-1,0,1]:
   for dx in [-1,0,1]:
    if not(dx or dy):continue
    q=(x+dx,y+dy)
    if 0<=q[0]<1024 and 0<=q[1]<1024 and S[q[1],q[0]]:
     nd=g+(1.41421356 if dx and dy else 1)
     if nd<dist.get(q,1e9):dist[q]=nd;prev[q]=p;heapq.heappush(h,(nd+np.hypot(q[0]-t[0],q[1]-t[1]),q))
 if t not in dist: raise ValueError(('disconnected',a,b,s,t))
 p=t;rr=[p]
 while p!=s:p=prev[p];rr.append(p)
 return rr[::-1]
def trace(points):
 out=[]
 for a,b in zip(points[:-1],points[1:]):
  r=route(a,b);out+=r if not out else r[1:]
 return np.array(out)
